/* Original scroll staging and typography; all visitor assets remain local. */
(() => {
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  let dispose = null;
  let preference = 'on';
  try { preference = localStorage.getItem('nz-slowly-motion') || 'on'; } catch {}
  const clamp = n => Math.max(0, Math.min(1, n));
  const ease = n => n < .5 ? 4 * n * n * n : 1 - Math.pow(-2 * n + 2, 3) / 2;

  function letterTitle(heading) {
    if (heading.querySelector('.type-char')) return;
    const readable = heading.cloneNode(true);
    readable.querySelectorAll('br').forEach(br => br.replaceWith(document.createTextNode(' ')));
    const label = heading.dataset.readableTitle || readable.textContent.replace(/\s+/g, ' ').trim();
    heading.setAttribute('aria-label', label);
    heading.classList.add('type-reveal');
    let count = 0;
    const texts = [];
    const walker = document.createTreeWalker(heading, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) texts.push(walker.currentNode);
    for (const text of texts) {
      const fragment = document.createDocumentFragment();
      const tokens = text.textContent.normalize('NFC').match(/[A-Za-z0-9\u0100-\u017f'’\-]+|\s+|./gu) || [];
      for (const token of tokens) {
        if (/^\s+$/.test(token)) { fragment.append(document.createTextNode(token)); continue; }
        const word = document.createElement('span');
        word.className = 'type-word';
        word.setAttribute('aria-hidden', 'true');
        for (const char of Array.from(token)) {
          const letter = document.createElement('span');
          letter.className = 'type-char';
          letter.style.setProperty('--letter-delay', `${Math.min(count++, 22) * 22}ms`);
          letter.textContent = char;
          word.append(letter);
        }
        fragment.append(word);
      }
      text.replaceWith(fragment);
    }
  }

  window.initSiteMotion = function initSiteMotion() {
    if (dispose) dispose();
    const controller = new AbortController(), signal = controller.signal;
    let frame = 0, observer = null;
    const enabled = preference !== 'off' && !reduce.matches;
    const chinese = document.documentElement.lang.startsWith('zh');
    document.documentElement.classList.toggle('motion-off', !enabled);
    document.documentElement.classList.add('motion-ready');
    const toggle = document.querySelector('#motionToggle');
    if (toggle) {
      toggle.textContent = chinese ? (enabled ? '动效开' : '动效关') : (enabled ? 'Motion on' : 'Motion off');
      toggle.setAttribute('aria-pressed', String(enabled));
      toggle.title = reduce.matches ? (chinese ? '系统已启用减少动态效果' : 'Reduced motion is enabled in system settings') : (chinese ? '切换页面动态效果' : 'Toggle page motion');
      toggle.addEventListener('click', () => {
        preference = enabled ? 'off' : 'on';
        try { localStorage.setItem('nz-slowly-motion', preference); } catch {}
        if (typeof render === 'function') render(); else window.initSiteMotion();
      }, {signal});
    }

    document.querySelectorAll('main h1, main h2, .cinema-end-title').forEach(h => { if (!h.closest('.cinema-hero, .home-shortlist')) letterTitle(h); });
    const targets = [...document.querySelectorAll('.type-reveal, .route-card, .prepare-card, .map-wrap, .field-opening>div, .section-heading>p, .map-intro, .journey-intro, .future-reserve, .home-shortlist > div:first-child > img')];
    targets.forEach(el => { if (!el.classList.contains('type-reveal')) el.classList.add('motion-reveal'); });
    if (!enabled || !('IntersectionObserver' in window)) targets.forEach(el => el.classList.add('is-visible'));
    else {
      observer = new IntersectionObserver(entries => {
        for (const entry of entries) if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      }, {threshold: .04, rootMargin: '0px 0px -6% 0px'});
      targets.forEach(el => observer.observe(el));
    }

    const hero = document.querySelector('.cinema-hero'), stage = hero?.querySelector('.cinema-stage');
    document.documentElement.classList.toggle('cinematic-home', !!hero);
    const heroCopy = hero?.querySelector('.cinema-copy'), image = hero?.querySelector('.cinema-image');
    let heroTop = 0, viewport = innerHeight, started = performance.now();
    function measure() {
      viewport = Math.max(1, innerHeight);
      heroTop = hero ? hero.getBoundingClientRect().top + scrollY : 0;
      schedule();
    }
    function draw(now = performance.now()) {
      frame = 0;
      if (!hero || !stage) return;
      const distance = Math.max(0, scrollY - heroTop);
      const progress = clamp(distance / viewport);
      document.body.classList.toggle('past-cinema', distance >= viewport - 88);
      if (enabled) {
        const entered = clamp((now - started) / 1800);
        const settling = (1 - entered) * (1 - entered);
        const idle = entered >= 1 ? .015 * (1 - Math.cos((now - started - 1800) * Math.PI / 10000)) : 0;
        const scale = 1 + .06 * settling + Math.max(idle, .05 * progress);
        image.style.transform = `translate3d(0,${Math.min(distance * .3, viewport * .1)}px,0) scale(${scale})`;
        heroCopy.style.transform = `translate3d(0,${-44 * progress}px,0)`;
        heroCopy.style.opacity = String(clamp(1 - progress * 2));
        stage.style.setProperty('--hero-darkness', String(.18 * settling));
        if (distance < viewport && document.visibilityState === 'visible') frame = requestAnimationFrame(draw);
      } else {
        image.style.transform = '';
        heroCopy.style.transform = '';
        heroCopy.style.opacity = '';
        stage.style.removeProperty('--hero-darkness');
      }
    }
    function schedule() { if (!frame) frame = requestAnimationFrame(draw); }
    addEventListener('scroll', schedule, {passive:true, signal});
    addEventListener('resize', measure, {passive:true, signal});
    document.addEventListener('visibilitychange', schedule, {signal});
    reduce.addEventListener('change', () => window.initSiteMotion(), {signal});
    measure();
    dispose = () => {
      if (frame) cancelAnimationFrame(frame);
      observer?.disconnect();
      controller.abort();
      dispose = null;
    };
    addEventListener('pagehide', dispose, {once:true, signal});
  };
})();


