Object.assign(messages.en,{brandName:'Pounamu Atlas',heroLabel:'New Zealand travel guide',twoIslandsLabel:'North and South Islands',fieldLabel:'New Zealand travel guide',islandsLabel:'01 / North and South Islands',waysLabel:'Five ways to travel',picksLabel:'Selected routes',walkingLabel:'Ten walking routes',routesLabel:'All routes',prepareLabel:'Before you go',packingLabel:'Packing list',mapWaterLabel:'Schematic map · not for navigation',cookStraitLabel:'Cook Strait',introLabel:'Explore New Zealand',relatedLabel:'More routes',newHeroTitle:'New Zealand<br><em>routes and itineraries</em>',newHeroDescription:'Explore walking, cycling, driving and public transport routes, with maps, stops and practical details.',heroExplore:'Browse routes',heroFoot:'NEW ZEALAND / ROUTE GUIDE',waysHeading:'Five ways to travel',waysDescription:'Browse routes for walking, cycling, driving, public transport or paddling.',picksHeading:'Selected routes',allRoutes:'See all routes ↗',catalogueTitle:'All routes',catalogueDescription:'Filter by island and transport, then open a guide for the map and practical details.',preparePageTitle:'Before you go',packingTitle:'Packing list',nationalFooter:'Pounamu Atlas: New Zealand routes and itinerary planning.',mapHeading:'Route map',mapKicker:'Route map',relatedTitle:'More routes',routeSubtitle:'Route, access, stops and practical details.',cinemaEndTitle:'Routes across<br><em>New Zealand</em>',cinemaScroll:'Scroll to explore',fieldOpeningTitle:'New Zealand route guides',fieldOpeningDescription:'Choose a route to see its start, duration, stops and practical details.',rankingTitle:'Ten walking routes',rankingDesc:'Ten walks from the route collection, with reasons and sources below.',travelNote:'Check NZTA road conditions and the linked official information before you go.'});

function recommendationSource(r){const source=r.sources?.[0];return source?`<a class="route-source" href="${escapeHtml(source.url)}" target="_blank" rel="noopener noreferrer">${lang==='zh'?'资料来源':'Source'}: ${escapeHtml(source.label)} ↗</a>`:''}

Object.assign(messages.zh,{walkDesc:'步道、起终点及行走时间。',cycleDesc:'自行车线路及交通接驳。',driveDesc:'自驾路线、道路与沿途停留。',transitDesc:'火车、巴士与渡轮线路。',introTitle:'新西兰地图',introDesc:'在地图上选择北岛或南岛的地点，浏览对应线路。拉奇乌拉目前暂无对应攻略。',mapScale:'地形与线路均为示意，不可用于导航。',plannerTitle:'规划新西兰行程',plannerLabel:'行程规划',plannerDesc:'先选落地城市、离开城市和天数，再挑想去的地方。行程每天都会写清路段、车程和住处；天数不够时，仍会按时把你带到离开城市，排不下的地点单独列出。',yourTrip:'选择行程条件',plannerSmall:'出发前请查看 NZTA 路况和各线路链接的官方信息。',mapTopLeft:'新西兰地图',mapTopRight:'北岛 · 南岛 · 拉奇乌拉',mapBottomLabel:'地形示意，不可用于导航 · 新西兰主要岛屿',mapSourceLabel:'地图数据：Natural Earth ↗'});
