Object.assign(messages.en,window.V3_MESSAGES?.en);Object.assign(messages.zh,window.V3_MESSAGES?.zh);
const qs=new URLSearchParams(location.search),page=document.body.dataset.page;
let lang=['zh','en'].includes(qs.get('lang'))?qs.get('lang'):'zh';
let mode=['walk','cycle','drive','transit','paddle'].includes(qs.get('mode'))?qs.get('mode'):'all';
let islandFilter=['north','south'].includes(qs.get('island'))?qs.get('island'):'all';
let lastPlan=null,plannerPending=false;
const t=key=>String(messages[lang][key]||messages.en[key]||key).replace(/\{routes\}/g,routes.length);
const pick=value=>Array.isArray(value)?value[lang==='zh'?1:0]:value;
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routeTitle=r=>lang==='zh'?r.zh:r.name;
const $=s=>document.querySelector(s);
function updateFilterUrl(){const query=new URLSearchParams({lang});if(mode!=='all')query.set('mode',mode);if(islandFilter!=='all')query.set('island',islandFilter);history.replaceState(null,'',location.pathname+'?'+query)}
function pageUrl(name,params={}){const query=new URLSearchParams({...params,lang});return name+'.html?'+query}
function routeUrl(id){return pageUrl('route',{id})}
function modeIcon(m){const shapes={paddle:'<path d="M3 19h26c-3 5.5-23 5.5-26 0Z"/><path d="m23 3-10 19"/><path d="m21.5 6 3.5 1.8-2 3.6-3.4-1.8Z"/><path d="M8 26c2 1 4 1 6 0s4-1 6 0 4 1 6 0"/>',walk:'<circle cx="15" cy="5" r="2"/><path d="m11 11 4-3 4 6 4 1M14 9l-3 9-5 7m6-9 6 4 2 6M11 12l-6 3"/>',cycle:'<circle cx="7" cy="22" r="6"/><circle cx="25" cy="22" r="6"/><path d="m7 22 7-12 11 12H7l-4-13h5m6 1h9m-1-5h4m-3 0 2 17"/>',drive:'<path d="m5 12 3-7h16l3 7 2 2v11H3V14l2-2Zm0 0h22M3 20h26M7 25v3m18-3v3M7 16h3m12 0h3"/>',transit:'<rect x="6" y="3" width="20" height="24" rx="4"/><path d="M6 17h20M9 27v3m14-3v3M10 22h2m8 0h2M10 7h12"/>'};return '<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(shapes[m]||shapes.transit)+'</svg>'}
function routeImage(r,hero=false,eager=false){const p=routePhotos[r.id];return `<img src="${p.src}" alt="${escapeHtml(pick(p.place))}" ${hero?'fetchpriority="high"':eager?'loading="eager"':'loading="lazy"'} decoding="async">`}
function card(r,i=0){return `<article class="route-card"><a class="route-card-link" href="${routeUrl(r.id)}" aria-label="${escapeHtml(t('readGuide')+' · '+routeTitle(r))}"><div class="route-visual">${routeImage(r,false,i<3)}<span class="route-kind">${modeIcon(r.mode)}${t(r.mode)}</span><span class="route-image-arrow" aria-hidden="true">↗</span></div><div class="route-body"><p class="route-place">${t(r.island==='north'?'northIsland':'southIsland')} / ${escapeHtml(pick(r.region))}</p><h3>${escapeHtml(routeTitle(r))}</h3><p class="route-summary">${lang==='zh'?'推荐理由（编辑推荐）：':'Why go (editorial): '}${escapeHtml(pick(r.summary))}</p>${[r.time,r.distance].map(pick).filter(Boolean).length?`<div class="route-quick-facts">${[r.time,r.distance].map(pick).filter(Boolean).map(v=>`<span>${escapeHtml(v.split(/[；;]/)[0])}</span>`).join('')}</div>`:''}${v3CardBadge(r)}<div class="route-readmore"><span>${t('readGuide')}</span><span>↗</span></div></div></a>${recommendationSource(r)}</article>`}
function filteredRoutes(){return routes.filter(r=>(islandFilter==='all'||r.island===islandFilter)&&(mode==='all'||r.mode===mode))}
function routeCountText(n){if(lang==='zh')return n+' '+t('routeCount');return n+' '+(Number(n)===1?'route to explore':t('routeCount'));}
function renderRoutes(){if(!$('#routeGrid'))return;const data=filteredRoutes();$('#routeGrid').innerHTML=data.map(card).join('');$('#routeCount').textContent=routeCountText(data.length);document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode))});document.querySelectorAll('[data-island]').forEach(b=>{b.classList.toggle('active',b.dataset.island===islandFilter);b.setAttribute('aria-pressed',String(b.dataset.island===islandFilter))});if(!$('#routeAtlas').hidden)renderAtlas(data)}
function renderPhotoCredits(){if(!$('#photoCreditsList'))return;$('#photoCreditsList').innerHTML=Object.values(photoLibrary).filter(p=>!p.placeholder).map(p=>`<div><strong>${escapeHtml(pick(p.place))}</strong><span>${escapeHtml(p.author)}</span><a href="${p.source}" target="_blank" rel="noopener noreferrer">Wikimedia Commons ↗</a><a href="${p.licenseUrl}" target="_blank" rel="noopener noreferrer">${escapeHtml(p.license)}</a></div>`).join('')}
// Home map pins open that place's destination page (walk-through H-09); Fiordland opens Milford Sound
const HOME_MAP_PLACES={'Auckland':'ni-akl','Rotorua':'ni-rot','Taupō':'ni-tpo','Wellington':'ni-wlg','Nelson':'si-nsn','Christchurch':'si-chc','Aoraki / Mt Cook':'si-mtc','Queenstown':'si-zqn','Fiordland':'si-mfd','Dunedin':'si-dud'};
function renderHome(){if(!$('#homeWays'))return;$('.hero-image').alt=lang==='zh'?'AI 生成的南阿尔卑斯意境图':'AI-generated Southern Alps landscape';$('#homeWays').innerHTML=['walk','cycle','drive','transit','paddle'].map((m,i)=>`<a href="${pageUrl('routes',{mode:m})}"><span class="way-top"><span>0${i+1}</span>${modeIcon(m)}</span><h3>${t(m)}</h3><p>${t(m+'Desc')}</p><span class="way-arrow">↗</span></a>`).join('');$('#homePicks').innerHTML=['hooker','ni-taranaki-falls','milford'].map(id=>card(routes.find(r=>r.id===id))).join('');document.querySelectorAll('[data-map-region]').forEach(a=>{const top=a.querySelector('[data-map-label-en]'),sub=a.querySelector('[data-map-label-zh]'),en=top?.dataset.mapLabelEn,zh=sub?.dataset.mapLabelZh,id=HOME_MAP_PLACES[en];a.setAttribute('href',id?`destination.html?id=${id}&lang=${lang}`:pageUrl('routes',{island:a.dataset.mapRegion}));if(id)a.setAttribute('aria-label',lang==='zh'?`${zh}：查看目的地`:`${en}: see the destination`);if(top&&sub){top.textContent=lang==='zh'?zh:en;sub.textContent=lang==='zh'?en:zh}});const credit=$('[data-hero-credit]');credit.textContent=lang==='zh'?'AI 生成的南阿尔卑斯意境图，不是某个具体地点的实景':'AI-generated image of the Southern Alps, not a photo of a specific place';renderPhotoCredits();const ids=['ni-rangitoto','ni-taranaki-falls','ni-huka','ni-manaia','ni-rotopounamu','hooker','keysummit','gunn','bridle','matheson'];$('#walkingShortlist').innerHTML=ids.map((id,i)=>{const r=routes.find(x=>x.id===id);return `<div class="walk-recommendation"><a class="walk-recommendation-link" href="${routeUrl(id)}"><span>${String(i+1).padStart(2,'0')}</span><img class="walk-thumb" src="${routePhotos[id].src}" alt="" loading="lazy"><strong>${escapeHtml(routeTitle(r))}</strong><span>↗</span></a><img class="walk-hover-photo" src="${routePhotos[id].src}" alt="" aria-hidden="true" loading="lazy"><p>${lang==='zh'?'推荐理由（编辑推荐）：':'Why go (editorial): '}${escapeHtml(pick(r.summary))}</p>${recommendationSource(r)}<p class="walk-photo-credit">${lang==='zh'?'摄影：':'Photo: '}<a href="${routePhotos[id].source}" target="_blank" rel="noopener noreferrer">${escapeHtml(routePhotos[id].author)}</a> · <a href="${routePhotos[id].licenseUrl}" target="_blank" rel="noopener noreferrer">${escapeHtml(routePhotos[id].license)}</a></p></div>`}).join('')}
function timelineLabel(at){return pick(at)}
function sourceLinks(r){return v3SourceLinks(r)}
function renderJourney(){if(page!=='route')return;const r=routes.find(r=>r.id===qs.get('id'));if(!r){$('#journeyDetail').innerHTML=`<section class="page-intro section"><h1>${t('notFound')}</h1><a class="text-link" href="${pageUrl('routes')}">${t('backRoutes')} ↗</a></section>`;return}const photo=routePhotos[r.id];const facts=[[t('duration'),pick(r.time),'time'],[t('distance'),pick(r.distance),'distance'],[t('difficulty'),pick(r.level),'level'],[t('travelBy'),t(r.mode),null]];const title=routeTitle(r).split(/[:：]/);const heading=escapeHtml(title.shift())+(title.length?'<span class="journey-title-sub">'+escapeHtml(title.join(' · ').trim())+'</span>':'');
$('#journeyDetail').innerHTML=`<div class="breadcrumbs section"><a href="${pageUrl('index')}">${t('backHome')}</a><span>/</span><a href="${pageUrl('routes',{island:r.island,mode:r.mode})}">${t(r.island==='north'?'northIsland':'southIsland')} · ${t(r.mode)}</a><span>/</span><span>${escapeHtml(routeTitle(r))}</span></div>${v3ClosureBanner(r)}<section class="journey-hero">${routeImage(r,true)}<div class="journey-hero-shade"></div><div class="journey-hero-content"><p class="journey-kicker">${escapeHtml(pick(r.region))} / ${t(r.mode)}</p><h1 data-readable-title="${escapeHtml(routeTitle(r))}">${heading}</h1><p class="journey-lead">${escapeHtml(pick(r.summary))}</p></div></section><div class="journey-facts section">${facts.map(f=>v3FactCell(r,...f)).join('')}</div><nav class="journey-tabs section" aria-label="Route sections"><a href="#route-map">${t('mapDetails')}</a><a href="#journey-overview">${t('overview')}</a><a href="#journey-timeline">${t('dayPlan')}</a><a href="#journey-notes">${t('fieldNotes')}</a><a href="#journey-sources">${t('sources')}</a></nav><section class="route-map-section section" id="route-map"><div class="section-heading"><div><p class="section-label">01 / ${t('mapKicker')}</p><h2>${t('mapHeading')}</h2></div><p>${t('mapHint')}</p></div><div id="routeMap"></div></section><div class="journey-layout section"><div class="journey-main"><section class="journey-section" id="journey-overview"><p class="section-label">02 / ${t('overview')}</p><h2>${t('journeyOverview')}</h2><p class="journey-intro">${escapeHtml(pick(r.intro))}</p><div class="journey-endpoints"><span>${t('start')}</span><strong>${escapeHtml(pick(r.ends))}</strong></div></section><section class="journey-section" id="journey-timeline"><p class="section-label">03 / ${t('dayPlan')}</p><h2>${escapeHtml(pick(r.planTitle))}</h2><div class="journey-timeline">${r.timeline.map((s,i)=>`<div class="timeline-stop"><time>${escapeHtml(timelineLabel(s.at)||String(i+1).padStart(2,'0'))}</time><div class="timeline-copy"><h3>${escapeHtml(pick(s.title))}</h3><p>${escapeHtml(pick(s.text))}</p></div></div>`).join('')}</div></section><section class="journey-section" id="journey-notes"><p class="section-label">04 / ${t('fieldNotes')}</p><h2>${t('practicalTitle')}</h2><div class="journey-tip-grid">${r.tips.map((tip,i)=>`<div class="journey-tip"><span>0${i+1}</span><h3>${escapeHtml(pick(tip.title))}</h3><p>${escapeHtml(pick(tip.text))}</p></div>`).join('')}</div></section>${pick(r.alternatives)?`<section class="journey-section journey-alternative"><p class="section-label">${t('anotherPace')}</p><h2>${t('alternativeTitle')}</h2><p>${escapeHtml(r.mode==="paddle"?(lang==="zh"?"想缩短的话，可以只划其中一段，或改成更短的一日往返。这是划船，不是换一条步行。":"To shorten it, paddle one section or a shorter out-and-back. This is a paddle, not a walk."):pick(r.alternatives))}</p></section>`:""}${v3SafetyPanel(r)}${v3VerifyPanel(r)}${v3SportsPanel(r)}<section class="journey-section" id="journey-sources"><p class="section-label">05 / ${t('sources')}</p><div class="journey-source-list">${sourceLinks(r)}</div><p class="journey-photo-credit">${t('photoLocation')}: ${escapeHtml(pick(photo.place))}<br><a href="${photo.source}" target="_blank" rel="noopener noreferrer">${escapeHtml(photo.author)}</a> · <a href="${photo.licenseUrl}" target="_blank" rel="noopener noreferrer">${escapeHtml(photo.license)}</a></p></section></div><aside class="journey-sidebar"><div class="journey-sidebar-inner"><p class="section-label">${t('tripEssentials')}</p><h3>${t('beforeSettingOff')}</h3><dl>${v3SideFact(r,'season')}${v3SideFact(r,'booking')}${v3SideFact(r,'access')}<dt>${t('foodWater')}</dt><dd>${escapeHtml(pick(r.food))}</dd><dt>${t('gear')}</dt><dd>${escapeHtml(pick(r.gear))}</dd></dl><a class="journey-action" href="${pageUrl('plan',{route:r.id,days:r.planDays||'',mode:r.mode,island:r.island})}"><span>${t('planDays')}</span><span>↗</span></a></div></aside></div><section class="related section"><p class="section-label">${t('relatedLabel')}</p><h2>${t('relatedTitle')}</h2><div class="route-grid">${routes.filter(x=>x.island===r.island&&x.mode!==r.mode).filter((x,i,a)=>a.findIndex(y=>y.mode===x.mode)===i).slice(0,3).map(card).join('')}</div></section><div class="journey-bottom section"><a href="${pageUrl('routes',{island:r.island,mode:r.mode})}">← ${t('backRoutes')}</a><span>${t('brandName')} / ${t('fieldGuide')}</span></div>`;renderRouteMap(r);v3RouteMapFallback(r);window.__routeForCards=r;if(window.pounamuGuide&&window.pounamuGuide.renderRoutePage)window.pounamuGuide.renderRoutePage(r,lang);window.enhanceJourneyMap?.(r);v3AfterJourney(r);document.title=routeTitle(r)+' — 绿石之地 · Pounamu Atlas'}
