document.addEventListener('click',e=>{const a=e.target.closest?.('[data-map-region],.atlas-route');if(!a||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();location.assign(a.getAttribute('href'))});

window.addEventListener('pageshow',e=>{if(e.persisted)render()});

matchMedia('(max-width:750px)').addEventListener('change',()=>{if(page==='route'){renderJourney();window.initSiteMotion?.()}});

// Restore links to sections after the page template and typography are ready.
function restorePageAnchor(){
  if(!location.hash)return;
  let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{return}
  const target=document.getElementById(id);
  if(!target||!document.querySelector('main')?.contains(target))return;
  const root=document.documentElement,previous=root.style.scrollBehavior;
  root.style.scrollBehavior='auto';target.scrollIntoView({block:'start'});root.style.scrollBehavior=previous;
}
window.addEventListener('load',()=>requestAnimationFrame(restorePageAnchor),{once:true});

/* Editorial photo chapters and an accessible zoom for the existing NZ overview. */
(()=>{
  const main=document.querySelector('body[data-page="index"] main');
  if(!main)return;
  const makeBand=({id,src,zh,en,descZh,descEn,author,source,license,licenseText='CC BY-SA 4.0'})=>{
    const section=document.createElement('section');section.className='photo-band';section.id=id;
    const img=document.createElement('img');img.src=src;img.alt='';img.loading='lazy';
    const content=document.createElement('div');content.className='photo-band-content';const heading=document.createElement('h2'),description=document.createElement('p');content.append(heading,description);
    const credit=document.createElement('div');credit.className='photo-band-credit';const sourceLink=document.createElement('a');sourceLink.href=source;sourceLink.target='_blank';sourceLink.rel='noopener noreferrer';sourceLink.textContent=author;const licenseLink=document.createElement('a');licenseLink.href=license;licenseLink.target='_blank';licenseLink.rel='noopener noreferrer';licenseLink.textContent=licenseText;credit.append(sourceLink,document.createTextNode(' · '),licenseLink);section.append(img,content,credit);
    function localize(){const isZh=document.documentElement.lang.startsWith('zh');heading.textContent=isZh?zh:en;description.textContent=isZh?descZh:descEn;img.alt=isZh?zh:en;sourceLink.setAttribute('aria-label',(isZh?'照片来源及摄影者：':'Photo source and photographer: ')+author)}
    localize();new MutationObserver(localize).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});return section;
  };
  const map=document.querySelector('#island-map'),walks=document.querySelector('.home-shortlist');
  if(map&&!document.querySelector('#wanaka-photo-band')) map.after(makeBand({id:'wanaka-photo-band',src:'assets/optimized/hero-aotearoa.webp',zh:'瓦纳卡湖 · 南岛',en:'Lake Wānaka · South Island',descZh:'从罗伊峰俯瞰湖湾与群山。',descEn:'Looking over the lake and mountains from Roys Peak.',author:'Sky_xe',source:'https://commons.wikimedia.org/wiki/File:Wanaka,_New_Zealand,_view_2.jpg',license:'https://creativecommons.org/licenses/by-sa/4.0/'}));
  if(walks&&!document.querySelector('#taupo-photo-band')) walks.before(makeBand({id:'taupo-photo-band',src:'assets/optimized/ni-kinloch.webp',zh:'陶波湖 · 北岛',en:'Lake Taupō · North Island',descZh:'从 Kinloch 湖畔眺望陶波湖的暮色。',descEn:'Evening light over Lake Taupō from Kinloch.',author:'David Broad',source:'https://commons.wikimedia.org/wiki/File:Lake_Taupo%2C_North_Island%2C_New_Zealand_-_panoramio.jpg',license:'https://creativecommons.org/licenses/by/3.0',licenseText:'CC BY 3.0'}));
  const svg=map?.querySelector('svg.nz-map'),wrap=map?.querySelector('.nz-map-wrap');if(!svg||!wrap)return;
  const bar=document.createElement('div');bar.className='map-zoom-controls';bar.setAttribute('role','group');
  const views=[['all','0 0 680 820','全国','All New Zealand'],['north','270 45 300 375','放大北岛','Zoom North Island'],['south','55 365 390 360','放大南岛','Zoom South Island']];
  views.forEach(([id,box,zh,en],index)=>{const b=document.createElement('button');b.type='button';b.dataset.mapZoom=id;b.setAttribute('aria-pressed',index?'false':'true');b.addEventListener('click',()=>{svg.setAttribute('viewBox',box);bar.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});bar.append(b)});
  function labels(){const isZh=document.documentElement.lang.startsWith('zh');bar.setAttribute('aria-label',isZh?'放大地图':'Map zoom');views.forEach(([id,box,zh,en])=>{bar.querySelector(`[data-map-zoom="${id}"]`).textContent=isZh?zh:en})}
  labels();new MutationObserver(labels).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});wrap.insertBefore(bar,svg);
  // The land silhouette itself also zooms; the buttons remain keyboard accessible.
  const land=svg.querySelector('.nzmap-land');if(land){land.style.cursor='zoom-in';land.addEventListener('click',event=>{const matrix=svg.getScreenCTM();if(!matrix)return;const point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const local=point.matrixTransform(matrix.inverse());bar.querySelector(`[data-map-zoom="${local.y<400?'north':'south'}"]`)?.click();});}
})();
